#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float2 amzp_pos;
uniform float amzp_preset;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
layout(color) uniform half4 amzp_color3;
uniform float amzp_brightness;
uniform float amzp_flicker;
uniform float amzp_streakAmt;
uniform float amzp_streakLen;
uniform float amzp_streakThick;
uniform float amzp_fineOn;
uniform float amzp_fineLines;
uniform float amzp_lineGap;
uniform float amzp_dispersion;
uniform float amzp_crossOn;
uniform float amzp_crossAmt;
uniform float amzp_coreSize;
uniform float amzp_coreOn;
uniform float amzp_glowOn;
uniform float amzp_glowAmt;
uniform float amzp_raysOn;
uniform float amzp_raysAmt;
uniform float amzp_rayCount;
uniform float amzp_rayLen;
uniform float amzp_ghostsOn;
uniform float amzp_ghostsAmt;
uniform float amzp_ghostCount;
uniform float amzp_ghostSize;
uniform float amzp_ghostSpread;
uniform float amzp_ghostShape;
uniform float amzp_seed;
uniform float amzp_gradMap;
uniform float amzp_gmTri;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmMid;
layout(color) uniform half4 amzp_gmBg;
uniform float amzp_overdrawOn;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        if (int(amzp_blendMode) == 0) return f;
        if (int(amzp_blendMode) == 1) return float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        if (int(amzp_blendMode) == 2) return float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        if (int(amzp_blendMode) == 4) { float oa = max(b.a, f.a); return float4(min(b.rgb + f.rgb, float3(oa)), oa); }
        return f + b * (1.0 - f.a);
    }
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pM = float4(amzp_gmMid.rgb * amzp_gmMid.a, amzp_gmMid.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        float4 c = (amzp_gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float4 lightFx(float3 L) { L = clamp(L, 0.0, 1.0); return float4(L, max(L.r, max(L.g, L.b))); }
    float2 flareT(float2 d) { float2 p = nmRot(float2(d.x, -d.y), -radians(amzp_angle)) / (max(amzp_scale * 2.0, 0.002) * max(amzp_stretch, float2(0.01))); return float2(p.x, -p.y); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 0.2) : p; }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    bool inside(float2 uv) { return uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0; }
    float4 layerAt(float2 uv) { return inside(uv) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float3 hue(float h) { return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
    float hh(float x) { return fract(sin(x * 91.345 + amzp_seed * 13.7) * 43758.5453); }
    float vn1(float x) { float i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(hh(i), hh(i + 1.0), f); }
    float hexD(float2 q) { q = abs(q); return max(q.x * 0.866025 + q.y * 0.5, q.y); }
    void nmMain() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float2 p = uv * W;
        float4 orig = layerAt(uv);
        float px = pxs();
        float S = min(W.x, W.y) / px;
        float2 C = W * 0.5 + float2(amzp_position.x, -amzp_position.y) * px;
        float2 P = C + float2(amzp_pos.x, -amzp_pos.y) * px;
        float2 q = (p - P) / px;
        float ph = prog(0.0);
        float2 qa = flareT(q);
        float r = length(qa);
        float3 c1, cA, cB;
        if (int(amzp_preset) == 1) { c1 = float3(1.0, 0.68, 0.3); cA = float3(1.0, 0.9, 0.5); cB = float3(1.0, 0.42, 0.22); }
        else if (int(amzp_preset) == 2) { c1 = float3(0.25, 0.9, 0.8); cA = float3(0.2, 1.0, 0.9); cB = float3(1.0, 0.3, 0.8); }
        else if (int(amzp_preset) == 3) { c1 = float3(1.0, 0.2, 0.15); cA = float3(1.0, 0.5, 0.2); cB = float3(1.0, 0.15, 0.4); }
        else if (int(amzp_preset) == 4) { c1 = float3(1.0); cA = float3(0.85, 0.92, 1.0); cB = float3(1.0, 0.95, 0.85); }
        else if (int(amzp_preset) == 5) { c1 = amzp_color1.rgb; cA = amzp_color2.rgb; cB = amzp_color3.rgb; }
        else { c1 = float3(0.3, 0.6, 1.0); cA = float3(0.3, 0.92, 1.0); cB = float3(0.7, 0.45, 1.0); }
        float fl = 1.0 + clamp(amzp_flicker, 0.0, 1.0) * (vn1(time * 9.0 + ph * 5.0) - 0.5) * 0.8;
        float3 L = float3(0.0);
        float cs = max(amzp_coreSize, 0.5);
        if ((amzp_coreOn>0.5)) L += float3(1.0) * (exp(-r / (cs * 0.45)) * 1.5 + exp(-r / cs) * 0.5) * amzp_glowAmt;
        if ((amzp_glowOn>0.5)) L += c1 * (exp(-r / (cs * 3.5)) * 0.8 + exp(-r / (cs * 14.0)) * 0.2) * amzp_glowAmt;
        float L1 = max(amzp_streakLen, 0.01) * S * 0.9;
        float ax = abs(qa.x);
        float th = max(amzp_streakThick, 0.3);
        float xp = exp(-2.0 * pow(ax / L1, 0.85));
        float yl = exp(-pow(qa.y / th, 2.0)) + 0.2 / (1.0 + pow(qa.y / (th * 6.0), 2.0));
        float disp = clamp(amzp_dispersion, 0.0, 1.0);
        float tx = clamp(ax / L1, 0.0, 1.0);
        float3 sc = mix(c1, mix(cA, cB, smoothstep(0.35, 1.0, tx)), disp * smoothstep(0.0, 0.5, tx) + (1.0 - disp) * 0.0);
        sc = mix(float3(1.0), sc, smoothstep(0.0, 0.12, tx));
        L += sc * xp * yl * 1.25 * amzp_streakAmt;
        float nl = (amzp_fineOn>0.5) ? clamp(floor(amzp_fineLines + 0.5), 0.0, 8.0) : 0.0;
        for (int i = 0; i < 8; i++) {
            float fi = float(i);
            if (fi >= nl) break;
            float sg = mod(fi, 2.0) < 0.5 ? 1.0 : -1.0;
            float yo = sg * (1.0 + floor(fi * 0.5) * 1.15) * max(amzp_lineGap, 1.0);
            float tl = (hh(fi + 31.0) - 0.5) * 0.03;
            float yy = qa.y - yo - qa.x * tl;
            float ll = L1 * (0.9 - 0.07 * fi) * (0.7 + 0.5 * hh(fi + 5.0));
            float xl = exp(-2.2 * pow(ax / ll, 0.9));
            float spk = 0.65 + 0.7 * vn1(qa.x / (S * 0.05) + fi * 9.0 + ph * 0.5);
            float thl = th * (0.18 + 0.1 * hh(fi + 8.0));
            float ln = exp(-pow(yy / thl, 2.0)) + 0.05 / (1.0 + pow(yy / (thl * 6.0), 2.0));
            float3 lc = mod(fi, 2.0) < 0.5 ? cA : cB;
            L += lc * xl * ln * spk * 0.9 * amzp_streakAmt / (1.0 + 0.12 * fi);
        }
        float Lc = L1 * 0.22;
        L += mix(float3(1.0), c1, 0.6) * exp(-2.0 * pow(abs(qa.y) / Lc, 0.9)) * exp(-pow(qa.x / (th * 0.9), 2.0)) * 0.8 * ((amzp_crossOn>0.5) ? amzp_crossAmt : 0.0) * amzp_streakAmt;
        float ang = atan(qa.y, qa.x) + ph * 0.3;
        float rc = max(amzp_rayCount, 2.0);
        float idx = floor(ang / 6.2831853 * rc + 0.5);
        float rlen = (0.45 + 0.9 * hh(mod(idx, rc) + 61.0)) * amzp_rayLen * S * 0.17;
        float sp = pow(abs(cos(ang * rc * 0.5)), 90.0);
        L += mix(float3(1.0), c1, 0.5) * sp * exp(-r / rlen) * (1.0 - exp(-r / (cs * 0.6))) * 0.6 * ((amzp_raysOn>0.5) ? amzp_raysAmt : 0.0);
        L += c1 * sp * exp(-r / (rlen * 0.25)) * 0.5 * amzp_raysAmt * 0.0;
        float ng = (amzp_ghostsOn>0.5) ? clamp(floor(amzp_ghostCount + 0.5), 0.0, 10.0) : 0.0;
        for (int i = 0; i < 10; i++) {
            float fi = float(i);
            if (fi >= ng) break;
            float t = (0.55 + fi * 0.27 + hh(fi + 3.0) * 0.22) * max(amzp_ghostSpread, 0.1);
            float2 g = P + (C - P) * t;
            float gr = S * (0.012 + 0.05 * hh(fi + 11.0)) * amzp_ghostSize;
            float2 gq = flareT((p - g) / px) / gr;
            int shp = int(amzp_ghostShape) == 3 ? int(mod(fi, 3.0)) : int(amzp_ghostShape);
            float sd = shp == 1 ? hexD(gq) : length(gq);
            float fillA = shp == 2 ? 0.05 : 0.22;
            float m = (1.0 - smoothstep(0.7, 1.0, sd)) * fillA;
            float rim = exp(-pow((sd - 0.92) / (shp == 2 ? 0.1 : 0.07), 2.0)) * (shp == 2 ? 0.7 : 0.45);
            float3 gc = mod(fi, 3.0) < 0.5 ? cA : (mod(fi, 3.0) < 1.5 ? cB : c1);
            gc = mix(gc, hue(fract(hh(fi + 21.0))), 0.12);
            L += gc * (m + rim) * amzp_ghostsAmt * (0.7 + 0.5 * hh(fi + 41.0));
        }
        L *= max(amzp_brightness, 0.0) * fl;
        amzOutput = nmBlend(orig, nmGradMap(lightFx(L)));
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
